<script setup lang="ts">import type {Point} from '../types/domain';import {fixed} from '../utils/format';import {rangeLabels} from '../constants/enums';defineProps<{rows:Point[]}>()</script><template><div class="table-wrap"><table><thead><tr><th>配对编号</th><th>量程</th><th>X</th><th>Y</th><th>差值 y−x</th><th>界限外</th></tr></thead><tbody><tr v-for="p in rows" :key="p.pair_id"><td>{{p.pair_id}}</td><td>{{rangeLabels[p.range_label]}}</td><td>{{fixed(p.x)}}</td><td>{{fixed(p.y)}}</td><td>{{fixed(p.difference??p.y-p.x)}}</td><td>{{p.outside_loa?'待复核':'—'}}</td></tr></tbody></table></div></template>
